-- ? MsSQL ??? ? Oracle ??? ????(??? ??). SYSTEM ?? ??.
CREATE OR REPLACE FUNCTION SYSTEM.MIG_ENC(p_raw RAW) RETURN RAW IS
  v_in RAW(2000); v_out RAW(2000); n INTEGER;
BEGIN
  IF p_raw IS NULL OR UTL_RAW.LENGTH(p_raw)=0 THEN RETURN NULL; END IF;
  v_in := p_raw; n := MOD(UTL_RAW.LENGTH(v_in),8);
  IF n>0 THEN FOR i IN 1..(8-n) LOOP v_in := UTL_RAW.CONCAT(v_in, HEXTORAW('20')); END LOOP; END IF;
  DBMS_OBFUSCATION_TOOLKIT.DESEncrypt(input=>v_in, key=>UTL_RAW.CAST_TO_RAW('hellios#'), encrypted_data=>v_out);
  RETURN v_out;
END;
/
